mapper.select:
select s.*, c.name clazzName from student s left join clazz c on s.clazz_id = c.id


        s.name like concat('%',#{name},'%')


        and s.degree = #{degree}


        and s.clazz_id = #{clazzId}


order by s.update_time desc

select s.id, s.name, s.no, s.gender, s.phone, s.id_card, s.is_college, s.address, s.degree, s.graduation_date, s.clazz_id, s.violation_count, s.violation_score, s.create_time, s.update_time, c.name clazzName from student s left join clazz c on s.clazz_id = c.id
s.name like concat('%',#{param.name},'%')
and s.degree = #{param.degree}
and s.clazz_id = #{param.clazzId}
order by s.update_time desc
